/* Aadharshila interface. All financial outcomes are retrieved from the API. */
const state={user:null,apps:[],selected:null,detail:null,evidence:null,history:[],participants:[],reviews:[],policies:[],monitor:null,page:'overview',search:'',filter:'ALL'};
const VIEWS=[['overview','Overview','◫'],['applications','Application queue','▤'],['new','New application','⊕'],['evidence','Evidence explorer','▥'],['financial','Financial assessment','₹'],['income','Income reconciliation','≍'],['intelligence','Evidence intelligence · ML','✧'],['property-review','Property review','⌂'],['sanction','Sanction readiness','✓'],['identity','KYC & fraud','♢'],['property','Property assessment','⌂'],['decision','Decision explanation','◎'],['requests','Evidence requests','✉'],['scenarios','Offers & stress tests','≋'],['documents','Document vault','▣'],['policy','Policy studio','⚖'],['simulation','Policy simulation','◈'],['audit','Audit timeline','◷'],['replay','Historical replay','↺'],['changes','Decision changes','⇄'],['monitoring','Monitoring','▦'],['connectors','Integrations','⌘'],['compliance','Regulatory sources','§']];
const $=(s)=>document.querySelector(s);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n)=>n===null||n===undefined?'—':'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:0});
const pct=(n)=>n===null||n===undefined?'—':(Number(n)*100).toFixed(1)+'%';
const safe=(v)=>esc(v??'—');
const badge=(v)=>`<span class="badge ${String(v||'neutral').toLowerCase().replace(/[^a-z]/g,'')}">${esc(v||'NOT AVAILABLE')}</span>`;
const when=(v)=>v?new Date(v).toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'}):'—';
const isStaff=()=>state.user&&state.user.role!=='BORROWER';
function csrf(){return (document.cookie.split('; ').find(s=>s.startsWith('aadharshila_csrf='))||'').split('=').slice(1).join('=');}
async function api(path,opts={}){
 const options={credentials:'same-origin',...opts,headers:{...(opts.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(opts.headers||{})}};
 if(['POST','PATCH','PUT','DELETE'].includes((opts.method||'GET').toUpperCase()))options.headers['X-CSRF-Token']=csrf();
 let r;try{r=await fetch('/api/v1'+path,options);}catch(e){throw new Error('Cannot reach local API. Check the server.')}
 let result;try{result=await r.json()}catch{result={detail:'Unexpected server response'}}
 if(!r.ok){if(r.status===401){state.user=null;showLogin()}throw new Error(typeof result.detail==='string'?result.detail:JSON.stringify(result.detail)||'Request failed')}
 return result;
}
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.style.background=error?'#9c4037':'#303c35';t.classList.remove('hidden');setTimeout(()=>t.classList.add('hidden'),3500)}
function showLogin(){ $('#login').classList.remove('hidden');$('#shell').classList.add('hidden'); }
function showApp(){ $('#login').classList.add('hidden');$('#shell').classList.remove('hidden');$('#account').textContent=state.user.username.replace('_',' ');$('#role').textContent=state.user.role.replace('_',' ');$('#avatar').textContent=state.user.username[0].toUpperCase();$('#today').textContent=new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Kolkata'});}
async function reload(){
 const [apps,policies,reviews]=await Promise.all([api('/applications'),state.user?.role==='BORROWER'?Promise.resolve({items:[]}):api('/policies'),api('/review-tasks')]);
 state.apps=apps.items;state.policies=policies.items;state.reviews=reviews.items;
 if(!state.selected||!state.apps.some(a=>a.id===state.selected))state.selected=state.apps[0]?.id||null;
 await loadSelected();
}
async function loadSelected(){
 if(!state.selected){state.detail=null;state.evidence=null;state.history=[];state.participants=[];return}
 const id=state.selected;
 const [detail,evidence,history,participants]=await Promise.all([api('/applications/'+id),api('/applications/'+id+'/evidence'),api('/applications/'+id+'/assessments'),api('/applications/'+id+'/participants')]);
 state.detail=detail;state.evidence=evidence;state.history=history.items;state.participants=participants.items;
}
async function go(page){state.page=page;await render();}
function nav(){ $('#nav').innerHTML=VIEWS.map(([key,name,icon])=>`<button class="nav-item ${state.page===key?'active':''}" data-page="${key}"><span class="nav-icon">${icon}</span>${esc(name)}</button>`).join('');$('#current-view-label').textContent=VIEWS.find(x=>x[0]===state.page)?.[1]||'Workspace';}
function header(title,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">Aadharshila / Lending operations</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${action}</div>`}
function panel(title,sub,contents,buttons=''){return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2>${sub?`<div class="panel-sub">${esc(sub)}</div>`:''}</div>${buttons}</div>${contents}</section>`}
function keyvals(entries){return `<div class="panel-body">${entries.map(([k,v])=>`<div class="keyval"><span>${esc(k)}</span><b>${v}</b></div>`).join('')}</div>`}
function reasons(items){return items?.length?items.map(r=>`<div class="reason"><span class="reason-icon">!</span><div><h3>${esc(r.code?.replaceAll('_',' ')||'Evidence request')}</h3><p>${esc(r.explanation||r.request_text||'')}</p></div></div>`).join(''):'<div class="muted small-text">No outstanding exceptions in this assessment.</div>'}
const approw=()=>state.detail?.application;
const result=()=>state.detail?.latest_assessment?.result;
const selectedPage=()=>state.apps.find(x=>x.id===state.selected);
function chooser(){return `<select class="select" id="case-choose" aria-label="Select application">${state.apps.map(a=>`<option value="${a.id}" ${a.id===state.selected?'selected':''}>${esc(a.reference)} · ${esc(a.applicant_name)}</option>`).join('')}</select>`}
function caseBanner(){const a=approw(),r=result();if(!a)return '<div class="alert">No application selected. Create a new application to continue.</div>';
 return `<div class="summary-banner"><div><div class="case-code">${esc(a.reference)} · ${a.product==='LAP'?'LOAN AGAINST PROPERTY':'HOME LOAN'} · REVISION ${a.revision}</div><h2>${esc(a.applicant_name)}</h2><p>${esc(a.location)} · ${esc(a.applicant_type.replace('_',' ').toLowerCase())} applicant · Requested ${money(a.amount)} over ${a.tenure_months} months</p></div><div class="flex wrap">${badge(r?.outcome||'DRAFT')}${chooser()}</div></div>`}
function metaCard(name,value,foot,kind=''){return `<article class="metric"><div class="metric-label">${esc(name)}</div><div class="metric-value ${kind}">${value}</div><div class="metric-foot">${esc(foot)}</div></article>`}
function renderOverview(){const a=approw(),r=result(),f=r?.financials;
 if(!a)return header('Overview','Your lending-operations workspace')+'<div class="alert">No applications. Create a new case to begin.</div>';
 const ev=state.evidence?.evidence||{},count=Object.values(ev).filter(x=>x.verification==='VERIFIED'&&!x.expired).length;
 return header('Underwriting overview','Every credit outcome is tied to explicit evidence and versioned policy.',`<div class="flex">${a.workflow==='DRAFT'?'<button class="button primary" data-action="submit-app">Submit application →</button>':''}<button class="button" data-page="applications">Application queue →</button></div>`)+caseBanner()+
 `<div class="cards">${metaCard('Current credit outcome',badge(r?.outcome),'Assessment revision '+(r?.evidence_revision||'—'))}${metaCard('Proposed monthly EMI',money(f?.emi),'Rate and tenure from active policy')}${metaCard('Debt service / income',pct(f?.foir),'Illustrative FOIR')}${metaCard('Verified evidence signals',count+'/9','Simulated fixture provider assertions')}</div>`+
 `<div class="grid-main"><div>${panel('Decision rationale','Deterministic policy and evidence checks',`<div class="panel-body">${reasons(r?.reasons)}${!r?.reasons?.length?'<div class="alert info">All configured mandatory gates currently pass in the local fixture assessment.</div>':''}</div>`,`<button class="button small" data-page="decision">Full decision →</button>`)}${panel('Financial position','Amounts in Indian rupees',keyvals([['Requested principal',money(a.amount)],['Accepted monthly income',money(f?.accepted_income)],['Existing monthly obligations',money(f?.existing_obligations)],['Accepted property value',money(f?.accepted_property_value)],['Loan to value',pct(f?.ltv)]]),`<button class="button small" data-page="financial">Explore →</button>`)}</div><div>${panel('Evidence coverage','Each item must have a current, supported status',`<div class="panel-body">${['identity','bank_income','income_support','bureau','ownership','legal','valuation','screening','obligations'].map(k=>`<div class="keyval"><span>${esc(k.replaceAll('_',' '))}</span>${badge(ev[k]?.expired?'EXPIRED':ev[k]?.verification||'MISSING')}</div>`).join('')}</div>`,`<button class="button small" data-page="evidence">Inspect evidence →</button>`)}${panel('Additional participants','Co-applicants and guarantors do not automatically add eligible income',`<div class="panel-body">${state.participants.length?state.participants.map(p=>`<div class="keyval"><span>${safe(p.relationship.replaceAll('_',' '))}</span><b>${safe(p.name)}</b></div>`).join(''):'<div class="muted small-text">No additional participants recorded.</div>'}</div>`)}${panel('Assessment identity','Reproducibility metadata',keyvals([['Policy version',safe(r?.policy_version)],['Evidence revision',safe(r?.evidence_revision)],['Engine version',safe(r?.engine_version)],['Assessment ID',`<span class="mono">${safe(state.detail.latest_assessment?.id?.slice(0,12))}…</span>`]]))}</div></div>`;
}
function renderQueue(){const filtered=state.apps.filter(a=>(state.filter==='ALL'||(a.product===state.filter))&&[a.reference,a.applicant_name,a.location].join(' ').toLowerCase().includes(state.search.toLowerCase()));
 return header('Application queue','Review mortgage requests, incomplete evidence and current routing decisions.',`<button class="button primary" data-page="new">+ New application</button>`)+
 `<div class="screen-tools"><input class="search" id="search-apps" value="${esc(state.search)}" placeholder="Find reference, borrower or city..."><select class="select" id="filter-product"><option value="ALL">All products</option><option value="HOME_LOAN" ${state.filter==='HOME_LOAN'?'selected':''}>Home loans</option><option value="LAP" ${state.filter==='LAP'?'selected':''}>Loan against property</option></select><span class="stat-pill">${filtered.length} results</span></div>`+
 panel('Active application register','Synthetic demonstration records alongside locally created applications',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Reference</th><th>Applicant</th><th>Product</th><th>Requested</th><th>Workflow</th><th>Outcome</th><th>Revision</th><th></th></tr></thead><tbody>${filtered.map(a=>`<tr class="click-row" data-select="${a.id}"><td class="mono">${esc(a.reference)}</td><td><b>${esc(a.applicant_name)}</b><small>${esc(a.location)}</small></td><td>${a.product==='LAP'?'LAP':'Home Loan'}</td><td>${money(a.amount)}</td><td>${badge(a.workflow)}</td><td>${badge(a.latest_outcome||'DRAFT')}</td><td>v${a.revision}</td><td><span class="card-link">Open →</span></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No matching cases.</td></tr>'}</tbody></table></div>`);
}
function renderNew(){return header('Create mortgage application','The borrower controls submission and financial-data consent.')+
 panel('Applicant and loan particulars','Fields are validated on the server; personal data in demo cases is synthetic.',`<form id="application-form" class="panel-body"><div class="form-grid"><label class="field">Loan product<select name="product"><option value="HOME_LOAN">Home Loan</option><option value="LAP">Loan Against Property</option></select></label><label class="field">Applicant category<select name="applicant_type"><option value="SALARIED">Salaried</option><option value="SELF_EMPLOYED">Self-employed</option></select></label><label class="field">Applicant full name<input required minlength="2" maxlength="150" name="applicant_name" placeholder="Enter applicant name"></label><label class="field">City / locality<input name="location" placeholder="e.g. Lucknow"></label><label class="field">Requested principal (₹)<input type="number" min="1" required name="amount" value="2500000"></label><label class="field">Tenure in months<input type="number" min="1" max="600" required name="tenure_months" value="180"></label><label class="field">Declared monthly income (₹)<input type="number" min="0" required name="declared_income" value="90000"></label><label class="field">Existing monthly debt service (₹)<input type="number" min="0" required name="existing_obligations" value="12000"></label><label class="field">Declared property value (₹)<input type="number" min="1" required name="property_value" value="4000000"></label><label class="field">Employer / business name<input name="employment" placeholder="Optional"></label><label class="field">Co-applicant name (optional)<input name="co_applicant_name" placeholder="Not added if blank"></label><label class="field">Guarantor name (optional)<input name="guarantor_name" placeholder="Not added if blank"></label></div><div class="form-footer"><button class="button primary" type="submit">Create draft application →</button></div></form>`)+
 '<div class="alert info">New borrower-provided values are self-reported. The application will be referred until mandatory independent evidence and valid consent are available.</div>';
}
function renderEvidence(){const ev=state.evidence?.evidence||{},a=approw();return header('Evidence explorer','Source, mode, freshness and verification stay separate throughout the decision.',a?.workflow==='DRAFT'?'<button class="button primary" data-action="submit-app">Submit application →</button>':'')+caseBanner()+
 panel('Available evidence','VERIFIED here means asserted by a deterministic fixture, not live issuer verification.',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Evidence</th><th>Value</th><th>Provider</th><th>Mode</th><th>Verification</th><th>Revision</th></tr></thead><tbody>${Object.keys(ev).sort().map(k=>{let e=ev[k];return `<tr><td><b>${esc(k.replaceAll('_',' '))}</b></td><td class="mono">${esc(JSON.stringify(e.value).slice(0,75))}</td><td>${esc(e.provider)}</td><td>${badge(e.mode)}</td><td>${badge(e.expired?'EXPIRED':e.verification)}</td><td>v${e.revision}</td></tr>`}).join('')||'<tr><td colspan="6">No evidence has been submitted.</td></tr>'}</tbody></table></div>`)+
 `<div class="grid-even">${panel('Financial-data consent','Purpose-specific permission and revocation',`<div class="panel-body"><p class="small-text muted">Purpose: financial underwriting. Permission does not imply provider onboarding.</p><div class="keyval"><span>Current permission</span>${badge(state.evidence?.consents?.includes('financial_underwriting')?'GRANTED':'NOT GRANTED')}</div>${state.user.role==='BORROWER'?'<div class="flex" style="margin-top:17px"><button class="button primary small" data-action="consent-grant">Grant consent</button><button class="button small" data-action="consent-revoke">Revoke</button></div>':'<p class="footnote">Only the borrower can authorize or revoke financial-data collection.</p>'}</div>`)}${panel('Submit corrected evidence','Verified fixture responses require analyst access.',`<form id="evidence-form" class="panel-body"><div class="form-grid"><label class="field">Evidence type<select name="key">${['bank_income','income_support','valuation','obligations','identity','bureau','ownership','legal','screening'].map(k=>`<option value="${k}">${k.replaceAll('_',' ')}</option>`).join('')}</select></label><label class="field">Amount / signal<input name="amount" placeholder="e.g. 95000, or CLEAR"></label><label class="field">Verification<select name="verification"><option value="UNRESOLVED">UNRESOLVED</option>${isStaff()?'<option value="VERIFIED">VERIFIED (simulation)</option><option value="FAILED">FAILED</option>':''}</select></label><label class="field">Mode<select name="mode"><option value="SELF_REPORTED">SELF_REPORTED</option>${isStaff()?'<option value="SIMULATED">SIMULATED</option>':''}</select></label></div><div class="form-footer"><button class="button primary small" type="submit">Record evidence & reassess</button></div></form>`)}</div>`+
 '<div class="alert">Document extraction never by itself qualifies as issuer verification. Provider outage and expired evidence remain unresolved.</div>';
}
function renderFinancial(){const r=result(),f=r?.financials,a=approw();if(!f)return header('Financial assessment','Assessment financials are unavailable.')+caseBanner();
 let cap=Math.max((f.accepted_income||0)*.6,1),emiRatio=Math.max(0,Math.min(100,f.emi/cap*100)),oldRatio=Math.max(0,Math.min(100,f.existing_obligations/cap*100));
 return header('Financial assessment','Trace calculated EMI, affordability and collateral constraints from evidence.')+caseBanner()+
 `<div class="cards">${metaCard('Monthly EMI',money(f.emi),'Configured illustrative rate')}${metaCard('Eligible monthly income',money(f.accepted_income),'From current bank evidence')}${metaCard('FOIR',pct(f.foir),'Debt service ÷ eligible income')}${metaCard('Loan to value',pct(f.ltv),'Principal ÷ accepted collateral')}</div><div class="grid-even">`+
 panel('Cash-flow composition','Loan servicing compared with verified monthly income',`<div class="panel-body"><div class="legend"><span>■ Existing obligations</span><span>■ Proposed EMI</span></div><div class="bar"><div style="background:#b9a28f;width:${oldRatio}%"></div><div style="background:#a85344;width:${emiRatio}%"></div></div>${keyvals([['Eligible monthly income',money(f.accepted_income)],['Proposed EMI',money(f.emi)],['Current obligations',money(f.existing_obligations)],['Monthly surplus',money(f.monthly_surplus)],['Total interest',money(f.total_interest)],['Total repayment',money(f.total_repayment)]]).replace('class="panel-body"','')}<p class="footnote">The income shown here is accepted for demonstration computation only. Independent income support must still pass before automatic approval.</p></div>`)+
 panel('Loan terms and policy','Illustrative lender parameters, not real Hero Housing credit policy',keyvals([['Product',safe(a.product)],['Loan principal',money(a.amount)],['Tenure',a.tenure_months+' months'],['Rate in use',safe(state.policies.find(p=>p.product===a.product&&p.state==='ACTIVE')?.config.annual_rate_percent)+'% pa'],['FOIR limit',pct(state.policies.find(p=>p.product===a.product&&p.state==='ACTIVE')?.config.max_foir)],['LTV limit',pct(state.policies.find(p=>p.product===a.product&&p.state==='ACTIVE')?.config.max_ltv)]]))+`</div>`+
 panel('Executed affordability controls','Policy version '+r.policy_version,`<div class="table-scroll"><table class="data-table"><thead><tr><th>Control</th><th>Result</th><th>Explanation</th></tr></thead><tbody>${r.rules.filter(x=>x.category==='policy'||x.category==='financial').map(x=>`<tr><td>${safe(x.code)}</td><td>${badge(x.status)}</td><td>${safe(x.detail)}</td></tr>`).join('')}</tbody></table></div>`);
}
function renderIdentity(){let r=result(),ev=state.evidence?.evidence||{};return header('KYC & fraud assessment','Potential matches and technical failures cannot be mistaken for confirmed findings.')+caseBanner()+
 `<div class="grid-even">${panel('Identity verification','Simulated source assertions',keyvals([['Applicant identity',badge(ev.identity?.verification||'MISSING')],['Credit bureau',badge(ev.bureau?.verification||'MISSING')],['Screening',badge(ev.screening?.verification||'MISSING')],['Screening mode',badge(ev.screening?.mode||'UNAVAILABLE')],['Potential match',badge(ev.screening?.value?.potential_match?'REVIEW REQUIRED':'NONE REPORTED')]]))}${panel('Fraud & contradictions','Signal does not equal proven wrongdoing',`<div class="panel-body">${reasons(r?.reasons?.filter(x=>['SCREENING_POTENTIAL_MATCH','PROVIDER_UNAVAILABLE','INCOME_CONTRADICTION'].includes(x.code)))}<p class="footnote">No covert device profiling. All screening signals are synthetic and require authorized validation.</p></div>`)}</div>`;
}
function renderProperty(){const a=approw(),ev=state.evidence?.evidence||{},r=result();return header('Property assessment','Collateral evidence, ownership, legal checks and valuation coverage are distinct.')+caseBanner()+
 `<div class="cards">${metaCard('Declared property value',money(a.property_value),'Borrower submitted')}${metaCard('Accepted valuation',money(r?.financials?.accepted_property_value),'From valuation evidence')}${metaCard('LTV',pct(r?.financials?.ltv),'Accepted collateral basis')}${metaCard('Ownership assessment',badge(ev.ownership?.verification||'UNRESOLVED'),'Independent legal dependency')}</div>`+
 `<div class="grid-even">${panel('Property verification','Neither a valuation nor document extraction establishes legal title.',keyvals([['Property locality',safe(a.location)],['Ownership evidence',badge(ev.ownership?.verification||'MISSING')],['Legal report',badge(ev.legal?.verification||'MISSING')],['Valuation report',badge(ev.valuation?.verification||'MISSING')],['Accepted collateral',money(r?.financials?.accepted_property_value)]]))}${panel('Conflicts and coverage','Known differences require specific supporting evidence.',`<div class="panel-body">${reasons(r?.reasons?.filter(x=>x.code.includes('PROPERTY')||x.code.includes('OWNERSHIP')||x.code.includes('LEGAL')||x.code.includes('VALUATION')))}<p class="footnote">The local fixtures are not a nationwide land registry or automatic title-verification system.</p></div>`)}</div>`;
}
function renderDecision(){const r=result(),a=approw();if(!r)return header('Decision explanation','No submitted assessment found.')+caseBanner();
 return header('Decision explanation','A deterministic outcome produced by explicit prerequisite checks.',`<a class="button" href="/api/v1/assessments/${state.detail.latest_assessment.id}/evidence-pack?format=html" target="_blank">Open evidence report ↗</a>`)+caseBanner()+
 `<div class="grid-main"><div>${panel('Final routing outcome','Evaluation trace · '+r.engine_version,`<div class="panel-body"><div class="explanation-title"><span class="big-outcome ${r.outcome.toLowerCase()}">${r.outcome}</span>${badge('REVISION '+r.evidence_revision)}</div><p class="muted" style="font-size:12px">${r.outcome==='APPROVE'?'All configured illustrative gates passed. This is not a regulated sanction.':r.outcome==='REFER'?'One or more mandatory checks remain unresolved. Manual review or additional evidence is required.':'A known mandatory demonstration policy threshold failed.'}</p><div class="divider"></div><h3>Decision reasons</h3>${reasons(r.reasons)}</div>`)}${panel('Rules applied','Missing evidence never becomes a successful check.',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Reason code</th><th>Category</th><th>Result</th></tr></thead><tbody>${r.rules.map(x=>`<tr><td class="mono">${safe(x.code)}</td><td>${safe(x.category)}</td><td>${badge(x.status)}</td></tr>`).join('')}</tbody></table></div>`)}</div><div>${panel('Decision passport','Reproducible identifiers and policy provenance',keyvals([['Application',safe(a.reference)],['Engine',safe(r.engine_version)],['Policy version',safe(r.policy_version)],['Evidence revision',safe(r.evidence_revision)],['Assessment ID',`<span class="mono">${safe(state.detail.latest_assessment.id.slice(0,14))}…</span>`],['Decision issued',when(state.detail.latest_assessment.created_at)]]))}${panel('Risk indicator','Non-statistical illustrative scorecard',keyvals([['Risk band',badge(r.risk?.band||'UNAVAILABLE')],['Model category',safe(r.risk?.type)],['Statistical default probability','NOT ESTIMATED'],['Training data','NOT TRAINED']]))}</div></div>`;
}
function renderRequests(){let tasks=state.reviews.filter(t=>t.application_id===state.selected);return header('Evidence requests','Exceptions are visible, attributable and cannot be silently overridden.')+caseBanner()+panel('Next useful evidence','Deterministic ranking based on missing prerequisites and conflicts.',`<div id="next-evidence" class="panel-body"><div class="muted">Loading recommendations…</div></div>`)+panel('Review and resolution queue','Closing a task does not turn an unverified input into a verified input.',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Reason</th><th>Request</th><th>Status</th><th>Action</th></tr></thead><tbody>${tasks.map(t=>`<tr><td><b>${safe(t.reason_code)}</b></td><td style="white-space:normal;max-width:370px">${safe(t.request_text)}</td><td>${badge(t.status)}</td><td>${isStaff()?`<button class="button small" data-task="${t.id}" data-task-action="${t.status==='OPEN'?'RESOLVE':'REOPEN'}">${t.status==='OPEN'?'Resolve':'Reopen'}</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No review tasks for this case.</td></tr>'}</tbody></table></div>`);
}
function renderScenarios(){const r=result();let alt=r?.alternative,scenarios=r?.stress||[];return header('Alternative offers & stress','Term adjustment and hypothetical sensitivity never bypass missing mandatory evidence.')+caseBanner()+
 `<div class="grid-even">${panel('Maximum calculated alternative','The nearest policy-permitted terms based on current financial evidence.',`<div class="panel-body">${alt?`<div class="big-outcome">${money(alt.principal)}</div><p class="muted small-text">Maximum illustrated principal under current FOIR and LTV constraints</p>${keyvals([['Tenure',alt.tenure_months+' months'],['EMI',money(alt.emi)],['FOIR',pct(alt.foir)],['LTV',pct(alt.ltv)],['Total interest',money(alt.total_interest)]]).replace('class="panel-body"','')}`:'<div class="empty">Verified income and valuation evidence required.</div>'}<p class="footnote">Not an approved offer. Changing terms requires the borrower’s acceptance and full re-underwriting.</p></div>`) }${panel('Scenario assumptions','What changes and what does not.',keyvals([['Income stress','-20% (illustrative)'],['Rate stress','+2 percentage points'],['Collateral stress','-15%'],['Decision effect','Only from configured explicit rules'],['All scenarios','Not forecasts']]))}</div>`+
 panel('Hypothetical stress matrix','Before / after EMI, FOIR, collateral LTV and policy check',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Scenario</th><th>EMI</th><th>FOIR</th><th>Monthly surplus</th><th>LTV</th><th>Policy</th></tr></thead><tbody>${scenarios.map(s=>`<tr><td><b>${safe(s.scenario)}</b></td><td>${money(s.emi)}</td><td>${pct(s.foir)}</td><td>${money(s.monthly_surplus)}</td><td>${pct(s.ltv)}</td><td>${badge(s.policy_result)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Valid financial evidence is required for scenario analysis.</td></tr>'}</tbody></table></div>`);
}
function renderIncome(){return header('Income reconciliation','Verified-source transactions are normalized conservatively. An analyst preview never updates the loan decision.')+caseBanner()+
 panel('Source transaction preview','Paste normalized transaction JSON from an independently authorized source.',`<form id="income-form" class="panel-body"><label class="field">Transaction batch JSON<textarea name="batch" rows="12" placeholder='{"applicant_type":"SALARIED","as_of":"2026-11-10","transactions":[...]}' required></textarea></label><p class="footnote">Only independently verified rows count. Own transfers, loan proceeds and uncertain credits are excluded. This preview cannot grant credit approval.</p><button class="button primary" type="submit" ${!isStaff()?'disabled':''}>Calculate reconciliation</button></form>`)+
 '<section class="panel"><div class="panel-head"><h2>Reconciliation findings</h2></div><div class="panel-body" id="income-results">Submit a structured transaction batch to review.</div></section>';
}
function renderIntelligence(){
 return header('Evidence intelligence','Explainable anomaly triage for synthetic statement transactions. Model findings never change the loan decision.')+caseBanner()+
 panel('Review synthetic bank activity','Isolation Forest · fixed synthetic reference · no live account access',
 `<div class="panel-body"><div class="alert info"><b>Advisory only.</b> Model outlier margins are not probabilities of fraud or default. This analysis does not verify transactions or alter accepted income, evidence, or policy decisions.</div>
 <div class="inline-actions"><button type="button" class="button small" id="intel-demo" data-action="intel-demo" ${!isStaff()?'disabled':''}>Load synthetic sample ↻</button><span class="muted small-text">Sample includes six monthly receipts, one outlier, a loan credit, and a duplicate entry.</span></div>
 <form id="intelligence-form"><label class="field">Transaction batch (structured JSON)<textarea id="intelligence-input" name="batch" rows="12" spellcheck="false" placeholder="Select Load synthetic sample to get started" required></textarea></label>
 <div class="form-footer"><button class="button primary" type="submit" ${!isStaff()?'disabled':''}>Run evidence analysis →</button></div></form></div>`)+
 panel('Model and evidence findings','Read-only prioritization with traceable, human-readable signals',
 '<div id="intelligence-results" class="panel-body"><div class="empty">Load a sample and run analysis to inspect what merits review.</div></div>');
}
async function fillIntelligenceDemo(){
 if(!state.selected||!isStaff())return;
 const input=$('#intelligence-input');if(!input)return;
 try{const result=await api('/applications/'+state.selected+'/evidence-intelligence/demo');
 if(input)input.value=JSON.stringify(result.sample,null,2);
 }catch(error){if(input)input.placeholder=error.message}
}
function showIntelligenceResults(r){
 const node=$('#intelligence-results');if(!node)return;
 const months=Object.entries(r.reconciliation.monthly_receipts||{}).sort(([a],[b])=>a.localeCompare(b));
 const max=Math.max(1,...months.map(([,value])=>Number(value)||0));
 const graph=months.map(([month,value])=>`<div class="intel-bar-row"><span class="mono">${safe(month)}</span><div class="intel-track"><span class="intel-fill" style="width:${Math.max(0,Math.min(100,(Number(value)/max)*100)).toFixed(1)}%"></span></div><b>${money(value)}</b></div>`).join('');
 const signals=(r.signals||[]).map(signal=>`<div class="intel-signal"><b>${safe(signal.code.replaceAll('_',' '))}</b><small>${safe(signal.origin)}</small><p>${safe(signal.explanation)}</p></div>`).join('');
 const outliers=(r.outlier_months||[]).map(x=>`<div class="intel-signal"><b>${safe(x.month)} · ${money(x.observed_receipts_inr)}</b><small>UNSUPERVISED ML · ${safe(x.relative_to_median)}× median receipts</small><p>Unusual relative monthly receipt pattern. Uncalibrated anomaly margin: ${safe(x.anomaly_margin)}. Review source evidence; this is not a fraud finding.</p></div>`).join('');
 node.innerHTML=`<div class="cards">${metaCard('Analyst income preview',money(r.reconciliation.accepted_monthly_income),'Not an accepted underwriting income')}${metaCard('Income difference',r.evidence_comparison.difference_ratio===null?'N/A':pct(r.evidence_comparison.difference_ratio),'Stored bank vs supporting income')}${metaCard('Flagged months',String((r.outlier_months||[]).length),'Synthetic-reference ML')}${metaCard('Assessment changed?',badge('NO'),'Review-only · no database writes')}</div>`+
 `<div class="panel-body"><h3>Monthly receipts in the submitted batch</h3><div class="intel-bars">${graph}</div><p class="footnote">Only verified-flagged rows from analyst-submitted JSON enter this preview. Their flags do not establish bank-source authenticity.</p>
 <h3>Model provenance</h3>${keyvals([['Detector',safe(r.model.name)],['Training reference',safe(r.model.reference)],['Model status',badge(r.model.status)],['Credit decision',badge('NOT USED')]])}
 <h3>Explainable review signals</h3>${signals||'<p class="muted">No rule-based signals.</p>'}
 <h3>ML anomaly observations</h3>${outliers||'<p class="muted">No months crossed the synthetic reference threshold.</p>'}
 <h3>Suggested reviewer actions</h3><ol>${(r.recommended_actions||[]).map(a=>`<li>${safe(a)}</li>`).join('')}</ol><div class="alert info">${safe(r.disclaimer)}</div></div>`;
}
function renderPropertyReview(){return header('Property intelligence','Comparable prices cannot establish ownership or legal title.')+caseBanner()+
 panel('Independent review input','This preview does not write verified property evidence.',`<form id="property-form" class="panel-body"><div class="form-grid"><label class="field">Area (m²)<input type="number" name="area_sqm" min="11" step="0.1" value="100" required></label><label class="field">Declared value (INR)<input type="number" name="declared_value_inr" min="1" value="5000000" required></label></div><label class="field">Comparable sales (JSON array)<textarea name="comparables" rows="6" placeholder='[{"sale_reference":"REGISTERED-REF","area_sqm":100,"sale_price_inr":5000000,"distance_km":2,"months_ago":6,"issuer_verified":false}]'></textarea></label><p class="footnote">Registry, CERSAI, RERA, legal opinion and independent valuation gates remain unresolved until supported by authorized evidence.</p><button class="button primary" type="submit" ${!isStaff()?'disabled':''}>Assess indicative comparables</button></form>`)+
 '<section class="panel"><div class="panel-head"><h2>Property review</h2></div><div class="panel-body" id="property-results">Submit comparable evidence to inspect coverage.</div></section>';
}
function renderSanction(){return header('Non-binding sanction readiness','A simulated underwriting result is not a loan sanction or Key Facts Statement.')+caseBanner()+
 '<section class="panel"><div class="panel-head"><h2>Prerequisite status</h2></div><div class="panel-body" id="sanction-results">Loading the assessment preview…</div></section>';
}
async function fillSanction(){if(!state.selected)return;
 try{const p=await api('/applications/'+state.selected+'/sanction-preview');const node=$('#sanction-results');if(!node)return;
 node.innerHTML=keyvals([['Preview classification',badge(p.type)],['Assessment outcome',badge(p.decision)],['Requested principal',money(p.principal_requested_inr)],['Illustrative EMI',money(p.illustrative_emi_inr)],['Borrower acceptance',badge(p.prerequisites.borrower_acceptance)],['Lender sanction',badge(p.prerequisites.lender_sanction_authority)],['Disbursement',badge(p.prerequisites.disbursement)]])+`<p class="footnote">${esc(p.disclaimer)}</p>`;
 }catch(e){toast(e.message,true)}
}
function renderDocuments(){return header('Document vault','Securely bounded upload and parsing. OCR, malware scanning and issuer checks are separate dependencies.')+caseBanner()+
 `<div class="grid-even">${panel('Upload document','PDF or UTF-8 text · max 8 MiB',`<form id="document-form" class="panel-body"><label class="field">Select file<input type="file" name="file" accept="application/pdf,text/plain,.pdf,.txt" required></label><p class="footnote">A document hash proves byte consistency, not authenticity. Parsed values never become verified financial evidence automatically.</p><div class="form-footer"><button class="button primary" type="submit">Upload and parse</button></div></form>`)}${panel('Document controls','Current capability boundaries',keyvals([['Text PDF extraction',badge('PARSED')],['Scanned PDF / OCR',badge('OPTIONAL OCR')],['Digital signature check',badge('NOT AUTOMATICALLY VERIFIED')],['Malware scanner',badge('NOT AUTOMATICALLY VERIFIED')],['Provider issuer validation',badge('NOT CONNECTED')]]))}</div><div id="document-list" class="panel"><div class="panel-head"><h2>Stored documents</h2></div><div class="empty">Loading documents…</div></div>`;
}
function renderPolicy(){return header('Policy studio','Write, validate, simulate, approve and activate demonstration policies with separate authorities.')+
 panel('Policy register','Policy rules are illustration assumptions; these are not lender-specific or automatically certified regulatory rules.',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Product</th><th>Version</th><th>State</th><th>FOIR</th><th>LTV</th><th>Rate</th><th>Governance</th></tr></thead><tbody>${state.policies.map(p=>`<tr><td>${safe(p.product)}</td><td class="mono">v${p.version}</td><td>${badge(p.state)}</td><td>${pct(p.config.max_foir)}</td><td>${pct(p.config.max_ltv)}</td><td>${p.config.annual_rate_percent}%</td><td><div class="inline-actions"><button class="button small" data-policy-action="validate" data-policy-id="${p.id}">Validate</button><button class="button small" data-policy-action="approve" data-policy-id="${p.id}">Approve</button><button class="button small" data-policy-action="activate" data-policy-id="${p.id}">Activate</button></div></td></tr>`).join('')}</tbody></table></div>`)+
 panel('Draft a new policy','Creates a new version using explicit threshold changes.',`<form id="policy-form" class="panel-body"><div class="form-grid"><label class="field">Product<select name="product"><option value="HOME_LOAN">Home Loan</option><option value="LAP">Loan Against Property</option></select></label><label class="field">FOIR limit (decimal)<input name="max_foir" type="number" min="0.01" max="1" step="0.01" value="0.48"></label><label class="field">LTV limit (decimal)<input name="max_ltv" type="number" min="0.01" max="1" step="0.01" value="0.75"></label><label class="field">Illustrative interest rate (%)<input name="annual_rate_percent" type="number" min="0" max="40" step="0.1" value="8.5"></label></div><div class="form-footer"><button type="submit" class="button primary">Save draft</button></div></form>`)+
 '<div class="alert info">Activation requires an independent policy approver and does not rewrite previously issued assessments.</div>';
}
function renderSimulation(){return header('Policy impact simulation','Replay stored synthetic case snapshots under a proposed policy. Original assessments remain unchanged.')+
 panel('Select policy version','Simulations execute against the persisted feature snapshots.',`<div class="panel-body"><div class="flex"><select id="simulate-choose" class="select">${state.policies.map(p=>`<option value="${p.id}">${p.product} / v${p.version} / ${p.state}</option>`).join('')}</select><button class="button primary" data-action="simulate">Run simulation</button></div><p class="footnote">No historical decision is overwritten. An increase in synthetic approvals is not a proven business improvement.</p></div>`)+`<div id="simulation-results"></div>`;
}
function renderAudit(){return header('Audit timeline','Append-only business events recording the actor, action, reason and reference.')+caseBanner()+panel('Recorded application events','Events are stored in the database; this is not cryptographically tamper-proof.',`<div class="panel-body" id="audit-list"><div class="empty">Loading events…</div></div>`);
}
function renderReplay(){const h=state.history;return header('Historical replay','Recompute from frozen evidence, policy and feature values—never from a live connector.')+caseBanner()+
 panel('Assessment versions','A new evidence revision preserves previous outcomes.',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Revision</th><th>Assessment</th><th>Outcome</th><th>Created</th><th>Action</th></tr></thead><tbody>${h.map(x=>`<tr><td>v${x.revision}</td><td class="mono">${esc(x.id.slice(0,14))}…</td><td>${badge(x.outcome)}</td><td>${when(x.created_at)}</td><td><button class="button small" data-replay="${x.id}">Replay and compare ↺</button></td></tr>`).join('')||'<tr><td colspan="5">No assessments available</td></tr>'}</tbody></table></div>`)+`<div id="replay-results"></div>`;
}
function renderChanges(){
 return header('Decision changes','Compare persisted underwriting assessments without rewriting prior decisions.')+caseBanner()+
 panel('Historical difference','Changes in outcome, blocking reasons and financial inputs are computed from stored assessment versions.',
 `<div class="panel-body" id="change-results"><div class="empty">Loading assessment comparison…</div></div>`);
}
function renderMonitoring(){return header('System monitoring','Real persisted counts, not invented performance measurements.')+`<div id="monitor-content"><div class="empty">Loading local metrics…</div></div>`;
}
function renderCompliance(){return header('Regulatory source register','Official RBI sources with clear boundaries: references pending clause-level validation.')+`<div id="compliance-content"><div class="empty">Loading sources…</div></div>`}
function renderConnectors(){return header('Integration matrix','Local fixture adapters demonstrate contract handling. All external provider connectivity is outstanding.')+`<div id="connector-content"><div class="empty">Loading integration matrix…</div></div>`;
}
const RENDER={overview:renderOverview,applications:renderQueue,new:renderNew,evidence:renderEvidence,financial:renderFinancial,identity:renderIdentity,property:renderProperty,decision:renderDecision,requests:renderRequests,scenarios:renderScenarios,income:renderIncome,intelligence:renderIntelligence,'property-review':renderPropertyReview,sanction:renderSanction,documents:renderDocuments,policy:renderPolicy,simulation:renderSimulation,audit:renderAudit,replay:renderReplay,changes:renderChanges,monitoring:renderMonitoring,connectors:renderConnectors,compliance:renderCompliance};
async function render(){nav();$('#content').innerHTML=RENDER[state.page]();if(state.page==='intelligence')fillIntelligenceDemo();if(state.page==='audit')fillAudit();if(state.page==='changes')fillChanges();if(state.page==='requests')fillNextEvidence();if(state.page==='documents')fillDocuments();if(state.page==='sanction')fillSanction();if(state.page==='monitoring')fillMonitoring();if(state.page==='connectors')fillConnectors();if(state.page==='compliance')fillCompliance();}
async function fillChanges(){if(!state.selected)return;const target=$('#change-results');if(!target)return;
 try{const diff=await api('/applications/'+state.selected+'/assessment-diff');
 target.innerHTML=keyvals([['Older revision',diff.older.revision],['Previous outcome',badge(diff.older.outcome)],['New revision',diff.newer.revision],['Current outcome',badge(diff.newer.outcome)],['Outcome changed',badge(diff.outcome_changed?'YES':'NO')]])+
 `<div class="panel-body"><h3>Changed reasons</h3>${(diff.reason_changes||[]).map(r=>`<div class="keyval"><span>${safe(r.reason_code)}</span><b>${badge(r.before)} → ${badge(r.after)}</b></div>`).join('')||'<p class="muted">No reason-code changes.</p>'}<h3>Financial changes</h3>${(diff.financial_changes||[]).map(x=>`<div class="keyval"><span>${safe(x.metric.replaceAll('_',' '))}</span><b>${safe(x.before)} → ${safe(x.after)}</b></div>`).join('')||'<p class="muted">No financial changes.</p>'}</div>`;
 }catch(e){target.innerHTML=`<div class="panel-body muted">${safe(e.message)}</div>`}}
async function fillNextEvidence(){if(!state.selected)return;const target=$('#next-evidence');if(!target)return;
 try{const res=await api('/applications/'+state.selected+'/next-evidence');target.innerHTML=(res.items||[]).map((item,i)=>`<div class="keyval"><span>${i+1}. ${safe(item.evidence_key.replaceAll('_',' '))}</span><b>${safe(item.request)}</b></div>`).join('')||'<p class="muted">No outstanding supported evidence requests.</p>';
 }catch(e){target.textContent=e.message}}
async function fillAudit(){if(!state.selected)return;try{const v=await api('/applications/'+state.selected+'/audit');$('#audit-list').innerHTML=`<div class="timeline">${v.items.map(e=>`<div class="timeline-item"><b>${esc(e.action.replaceAll('_',' '))} <span class="badge neutral">${esc(e.role)}</span></b><small>${when(e.timestamp)}</small><p>${esc(e.reason||JSON.stringify(e.detail||{}).slice(0,130))}</p></div>`).join('')||'<div class="empty">No events yet.</div>'}</div>`}catch(e){toast(e.message,true)}}
async function fillDocuments(){if(!state.selected)return;try{let v=await api('/applications/'+state.selected+'/documents');$('#document-list').innerHTML=panel('Stored documents','Original files are private and not exposed as unrestricted download URLs.',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Document</th><th>Size</th><th>Parse status</th><th>SHA-256</th><th>Access</th></tr></thead><tbody>${v.items.map(d=>`<tr><td>${safe(d.filename)}</td><td>${Math.ceil(d.byte_count/1024)} KiB</td><td>${badge(d.parse_status)}</td><td class="mono">${esc(d.sha256.slice(0,22))}…</td><td><a class="button small" href="/api/v1/applications/${state.selected}/documents/${d.id}/download">Download</a></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No documents uploaded yet.</td></tr>'}</tbody></table></div>`)}catch(e){toast(e.message,true)}}
async function fillMonitoring(){try{let v=await api('/monitoring/summary');$('#monitor-content').innerHTML=`<div class="cards">${metaCard('Total applications',v.applications,'Local database')}${metaCard('Current approvals',v.current_outcomes.APPROVE,'Not real lending sanctions')}${metaCard('Current referrals',v.current_outcomes.REFER,'Manual dependencies')}${metaCard('Policy rejections',v.current_outcomes.REJECT,'Illustrative policy thresholds')}</div>`+panel('Measurement provenance','Avoid conflating synthetic fixtures with production traffic.',keyvals([['Data source',safe(v.sample)],['Actual performance measurements',safe(v.operational_latency)],['Live provider round trips',safe(v.provider_latency)],['Cases with latest assessments',v.assessed]]))}catch(e){$('#monitor-content').innerHTML=`<div class="alert critical">${safe(e.message)}</div>`}}
async function fillConnectors(){try{
 let v=await api('/connectors');
 let calls=state.selected&&isStaff()?await api('/applications/'+state.selected+'/provider-calls'):{items:[]};
 $('#connector-content').innerHTML=caseBanner()+panel('Evidence provider readiness','A deterministic fixture is never a verified real-world provider.',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Provider category</th><th>Mode</th><th>Live verification</th><th>Local action</th></tr></thead><tbody>${v.items.map(x=>`<tr><td><b>${safe(x.name)}</b><small>${safe(x.note)}</small></td><td>${badge(x.mode)}</td><td>No</td><td>${isStaff()&&x.evidence_key?`<button class="button small" data-provider-run="${x.evidence_key}">Run fixture →</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`)+panel('Recent provider invocations','Only local fixture operations are available.',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Evidence key</th><th>Source mode</th><th>Result</th><th>Correlation ID</th></tr></thead><tbody>${calls.items.map(x=>`<tr><td>${safe(x.key)}</td><td>${badge(x.mode)}</td><td>${badge(x.status)}</td><td class="mono">${esc(x.request_id.slice(0,14))}…</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No connector invocations for this case.</td></tr>'}</tbody></table></div>`);
 }catch(e){toast(e.message,true)}}
async function fillCompliance(){try{let v=await api('/compliance/register');$('#compliance-content').innerHTML=panel('Research references','No automated regulatory certification is represented here.',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Authority / publication</th><th>Area</th><th>Version observed</th><th>Control status</th><th>Source</th></tr></thead><tbody>${v.items.map(x=>`<tr><td><b>${safe(x.name)}</b><small>${safe(x.authority)}</small></td><td>${safe(x.area)}</td><td>${safe(x.version)}</td><td>${badge('REVIEW PENDING')}</td><td><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Official page ↗</a></td></tr>`).join('')}</tbody></table></div>`)+`<div class="alert" style="margin:17px">Source references require applicability and clause-level interpretation by authorized professionals before becoming executable regulated controls.</div>`}catch(e){toast(e.message,true)}}
// Delegated events keep independently rendered modules functional.
document.addEventListener('click',async e=>{
 const page=e.target.closest('[data-page]');if(page){go(page.dataset.page);return}
 const row=e.target.closest('[data-select]');if(row){state.selected=row.dataset.select;await loadSelected();go('overview');return}
 const task=e.target.closest('[data-task]');if(task){const reason=prompt('Review resolution reason (no overrides of required evidence):');if(!reason)return;try{await api('/review-tasks/'+task.dataset.task+'/actions',{method:'POST',body:JSON.stringify({action:task.dataset.taskAction,reason})});await reload();render();toast('Task action recorded.')}catch(err){toast(err.message,true)}return}
 const replay=e.target.closest('[data-replay]');if(replay){try{const v=await api('/assessments/'+replay.dataset.replay+'/replay',{method:'POST'});$('#replay-results').innerHTML=panel('Replay verification','Frozen historical inputs · No provider calls',keyvals([['Outcome reproduced',badge(v.reproduced?'PASS':'FAIL')],...Object.entries(v.checks).map(([k,val])=>[k,badge(val?'PASS':'FAIL')]),['Original outcome',badge(v.original_outcome)],['Replayed outcome',badge(v.replayed_outcome)]]));toast(v.reproduced?'Historical decision reproduced.':'Replay mismatch detected.',!v.reproduced)}catch(err){toast(err.message,true)}return}
 const provider=e.target.closest('[data-provider-run]');if(provider){try{let v=await api('/applications/'+state.selected+'/providers/'+provider.dataset.providerRun+'/run',{method:'POST'});await reload();await render();toast('Fixture '+v.status+' · '+v.mode+(v.error_category?' · '+v.error_category:''),v.status!=='SUCCESS')}catch(err){toast(err.message,true)}return}
 const policy=e.target.closest('[data-policy-action]');if(policy){try{let actionName=policy.dataset.policyAction;let body; if(['approve','activate'].includes(actionName)){let reason=prompt('Record the governance reason (minimum 12 characters).');if(!reason)return;body=JSON.stringify({reason});}let res=await api('/policies/'+policy.dataset.policyId+'/'+actionName,{method:'POST',body});toast('Policy '+res.state.toLowerCase());await reload();render()}catch(err){toast(err.message,true)}return}
 const action=e.target.closest('[data-action]');if(action){try{
   if(action.dataset.action.startsWith('consent-')){const granted=action.dataset.action==='consent-grant';await api('/applications/'+state.selected+'/consents',{method:'POST',body:JSON.stringify({purpose:'financial_underwriting',granted,provider:'borrower',categories:['financial','credit']})});await reload();await render();toast(granted?'Consent recorded.':'Consent revoked.')}
   if(action.dataset.action==='intel-demo'){await fillIntelligenceDemo();toast('Synthetic transaction sample loaded.')}
   if(action.dataset.action==='submit-app'){await api('/applications/'+state.selected+'/submit',{method:'POST'});await reload();await go('decision');toast('Application submitted and assessed.')}
   if(action.dataset.action==='simulate'){let id=$('#simulate-choose').value;let v=await api('/policies/'+id+'/simulate',{method:'POST'});$('#simulation-results').innerHTML=panel('Simulation results',v.evaluated+' persisted synthetic assessments evaluated',`<div class="panel-body"><div class="cards" style="grid-template-columns:repeat(3,1fr)">${metaCard('Simulated approvals',v.simulated_counts.APPROVE,'Previously '+v.original_counts.APPROVE)}${metaCard('Simulated referrals',v.simulated_counts.REFER,'Previously '+v.original_counts.REFER)}${metaCard('Simulated rejections',v.simulated_counts.REJECT,'Previously '+v.original_counts.REJECT)}</div><h3>Changed outcomes</h3>${v.changes.map(x=>`<div class="keyval"><span>${safe(x.reference)}</span><b>${badge(x.old)} → ${badge(x.new)}</b></div>`).join('')||'<p class="muted small-text">No current outcome changes under this version.</p>'}</div>`);toast('Policy simulation complete.')}
 }catch(err){toast(err.message,true)}return}
});
document.addEventListener('change',async e=>{if(e.target.id==='case-choose'){state.selected=e.target.value;await loadSelected();render()}if(e.target.id==='filter-product'){state.filter=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='search-apps'){state.search=e.target.value;const pos=e.target.selectionStart;render();$('#search-apps')?.focus();$('#search-apps')?.setSelectionRange(pos,pos)}});
document.addEventListener('submit',async e=>{
 const form=e.target;if(form.id==='login-form')return;
 e.preventDefault();try{
 if(form.id==='application-form'){
  let d=Object.fromEntries(new FormData(form));for(let k of ['amount','tenure_months','declared_income','existing_obligations','property_value'])d[k]=Number(d[k]);
  let co=d.co_applicant_name,gu=d.guarantor_name;delete d.co_applicant_name;delete d.guarantor_name;
  let a=await api('/applications',{method:'POST',body:JSON.stringify(d)});
  for(const [name,relationship] of [[co,'CO_APPLICANT'],[gu,'GUARANTOR']])if(name?.trim())await api('/applications/'+a.id+'/participants',{method:'POST',body:JSON.stringify({name:name.trim(),relationship,accepted_monthly_income:0})});
  state.selected=a.id;await reload();await go('evidence');toast('Draft saved. Provide consent and evidence before submission.');
 }
 if(form.id==='evidence-form'){
  let f=Object.fromEntries(new FormData(form)),n=Number(f.amount),value;
  if(['bank_income','income_support','valuation','obligations'].includes(f.key)){if(!Number.isFinite(n)||f.amount==='')throw new Error('Enter a numeric amount');value={amount:n}}
  else if(f.key==='screening')value={potential_match:f.amount.trim().toLowerCase()==='true'};
  else value={status:f.amount||'RECEIVED'};
  await api('/applications/'+state.selected+'/evidence',{method:'POST',body:JSON.stringify({...f,value,provider:f.mode==='SIMULATED'?'local-review-fixture':'borrower'})});await reload();render();toast('Evidence revision saved and assessed.');
 }
 if(form.id==='income-form'){
  if(!state.selected)throw new Error('Select an application first.');
  let body=JSON.parse(new FormData(form).get('batch'));
  const r=await api('/applications/'+state.selected+'/income-reconciliation',{method:'POST',body:JSON.stringify(body)});
  $('#income-results').innerHTML=keyvals([['Reconciliation status',badge(r.status)],['Accepted monthly income (preview only)',money(r.accepted_monthly_income)],['Observed obligations',money(r.observed_monthly_obligations)],['Verified rows',r.verified_records],['Excluded unverified rows',r.unverified_records]])+`<p class="footnote">${esc(r.findings.join(', ')||'No additional flags')} · Does not update an underwriting decision.</p>`;
 }
 if(form.id==='intelligence-form'){
  if(!state.selected)throw new Error('Select an application first.');
  const body=JSON.parse(new FormData(form).get('batch'));
  const response=await api('/applications/'+state.selected+'/evidence-intelligence',{method:'POST',body:JSON.stringify(body)});
  showIntelligenceResults(response);toast('Advisory evidence analysis completed; no assessment changed.');
 }
 if(form.id==='property-form'){
  const entries=Object.fromEntries(new FormData(form));
  const body={area_sqm:Number(entries.area_sqm),declared_value_inr:Number(entries.declared_value_inr),comparables:entries.comparables.trim()?JSON.parse(entries.comparables):[]};
  const r=await api('/applications/'+state.selected+'/property-review-preview',{method:'POST',body:JSON.stringify(body)});
  $('#property-results').innerHTML=keyvals([['Review status',badge(r.status)],['Eligible comparable sales',r.comparable_count],['Indicative comparable estimate',money(r.indicative_median_valuation_inr)],['Accepted collateral value',badge('NOT VERIFIED')],['Unresolved checks',safe(r.missing_controls.join(', '))]])+`<p class="footnote">${esc(r.disclaimer)}</p>`;
 }
 if(form.id==='document-form'){
  const data=new FormData(form),r=await api('/applications/'+state.selected+'/documents',{method:'POST',body:data});await reload();render();toast('Document stored: '+r.status);
 }
 if(form.id==='policy-form'){
  let v=Object.fromEntries(new FormData(form));let p=state.policies.find(p=>p.product===v.product&&p.state==='ACTIVE');if(!p)throw new Error('Active policy missing');
  let cfg={...p.config,max_foir:Number(v.max_foir),max_ltv:Number(v.max_ltv),annual_rate_percent:Number(v.annual_rate_percent)};
  let res=await api('/policies',{method:'POST',body:JSON.stringify({product:v.product,config:cfg})});await reload();render();toast('New policy draft v'+res.version+' created.');
 }
 }catch(err){toast(err.message,true)}
});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();$('#login-error').textContent='';try{let r=await api('/auth/login',{method:'POST',body:JSON.stringify({username:$('#username').value,password:$('#password').value})});state.user=await api('/auth/me');showApp();await reload();go('overview')}catch(err){$('#login-error').textContent=err.message}});
$('#logout').addEventListener('click',async()=>{try{await api('/auth/logout',{method:'POST'})}catch{}state.user=null;showLogin()});
$('#refresh').addEventListener('click',async()=>{try{await reload();render();toast('Workspace refreshed')}catch(err){toast(err.message,true)}});
(async()=>{try{let meta=await api('/meta');if(meta.demo_enabled)$('#password').value='Demo@12345';else $('#login-form').classList.add('hidden');if(meta.sso_enabled)$('#sso-button').classList.remove('hidden')}catch{}try{state.user=await api('/auth/me');showApp();await reload();await render()}catch{showLogin()}})();
